import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';

const EnhancedBillUpload = () => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [processingStatus, setProcessingStatus] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    checkProcessingStatus();
  }, []);

  const checkProcessingStatus = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/bills/processing-status', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProcessingStatus(response.data);
    } catch (error) {
      console.error('Error checking processing status:', error);
    }
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFile(e.dataTransfer.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleFileSelect = (e) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setError('Please select a file first');
      return;
    }

    setUploading(true);
    setError(null);
    setResult(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post('http://localhost:8000/upload', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: `Bearer ${token}`,
        },
      });

      setResult(response.data);
      setFile(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (error) {
      console.error('Upload error:', error);
      setError(error.response?.data?.detail || 'An error occurred while processing the bill');
    } finally {
      setUploading(false);
    }
  };

  const formatCurrency = (amount, currency = 'INR') => {
    if (!amount && amount !== 0) return 'N/A';
    const symbol = currency === 'INR' ? '₹' : currency === 'USD' ? '$' : currency;
    return `${symbol}${parseFloat(amount).toFixed(2)}`;
  };

  const getConfidenceColor = (score) => {
    if (score >= 0.8) return 'badge badge-success';
    if (score >= 0.6) return 'badge badge-warning';
    return 'badge badge-danger';
  };

  const getParsingMethodBadge = (method) => {
    const textMap = {
      gemini_2_flash: 'Gemini 2.0 Flash',
      regex_fallback: 'Regex Parser',
      gemini_regex_hybrid: 'Hybrid (AI + Regex)',
      enhanced: 'Enhanced Pipeline',
    };
    return <span className="badge badge-info">{textMap[method] || method || 'Unknown'}</span>;
  };

  return (
    <div className="container-page">
      <div className="page-header">
        <div className="title">AI-Powered Bill Processing</div>
        <div className="subtitle">Upload your bills and let our AI extract data with high accuracy</div>
      </div>

      {processingStatus && (
        <div className="status-grid section">
          <div className="status-card card-hover">
            <div className="title">📸 OCR Extraction</div>
            <div className={processingStatus.services.ocr_space?.available ? 'badge badge-success' : 'badge badge-danger'}>
              {processingStatus.services.ocr_space?.available ? 'Ready' : 'Offline'}
            </div>
          </div>
          <div className="status-card card-hover">
            <div className="title">🧠 Gemini AI</div>
            <div className={processingStatus.services.gemini?.available ? 'badge badge-success' : 'badge badge-danger'}>
              {processingStatus.services.gemini?.available ? 'Ready' : 'Offline'}
            </div>
          </div>
          <div className="status-card card-hover">
            <div className="title">🔍 Pattern Fallback</div>
            <div className={processingStatus.services.regex_fallback?.available ? 'badge badge-success' : 'badge badge-danger'}>
              {processingStatus.services.regex_fallback?.available ? 'Ready' : 'Offline'}
            </div>
          </div>
        </div>
      )}

      <div
        className={`file-drop-area ${dragActive ? 'drag-active' : ''}`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*,application/pdf"
          onChange={handleFileSelect}
          style={{ display: 'none' }}
        />
        <div className="file-drop-content">
          <div className="file-icon">📄</div>
          <div className="page-description">
            Drag & drop your bill image or PDF here, or
          </div>
          <button type="button" className="btn btn-secondary file-select-btn">
            Browse Files
          </button>
        </div>
      </div>

      {file && (
        <div className="selected-file-info">
          <div className="file-details">
            <div><strong>Selected:</strong> {file.name}</div>
            <div className="text-muted">{(file.size / 1024).toFixed(2)} KB</div>
          </div>
          <div className="file-actions">
            <button type="button" className="btn btn-primary" onClick={handleUpload} disabled={uploading}>
              {uploading ? 'Uploading...' : 'Upload & Process'}
            </button>
            <button type="button" className="btn btn-outline" onClick={() => { setFile(null); if (fileInputRef.current) fileInputRef.current.value = ''; }}>
              Clear
            </button>
          </div>
        </div>
      )}

      {error && (
        <div className="message error section">
          {error}
        </div>
      )}

      {result && (
        <div className="results-container section">
          <div className="results-header">
            <div className="results-info">
              Parsed with {getParsingMethodBadge(result.parsing_method)}
            </div>
            {typeof result.confidence === 'number' && (
              <div className={getConfidenceColor(result.confidence)}>
                Confidence: {(result.confidence * 100).toFixed(0)}%
              </div>
            )}
          </div>

          <div className="results-grid">
            <div className="result-card">
              <h3>Bill Amount</h3>
              <p>{formatCurrency(result.amount, result.currency)}</p>
            </div>
            <div className="result-card">
              <h3>Date</h3>
              <p>{result.date || 'N/A'}</p>
            </div>
            <div className="result-card">
              <h3>Vendor</h3>
              <p>{result.vendor || 'N/A'}</p>
            </div>
            <div className="result-card">
              <h3>Category</h3>
              <p>{result.category || 'N/A'}</p>
            </div>
          </div>

          {result.raw_text && (
            <div className="raw-text-section">
              <h3>Extracted Text</h3>
              <div className="raw-text-container">
                <pre>{result.raw_text}</pre>
              </div>
            </div>
          )}

          <div className="result-actions">
            <button type="button" className="btn btn-secondary" onClick={() => navigator.clipboard.writeText(JSON.stringify(result, null, 2))}>
              Copy JSON
            </button>
            <button type="button" className="btn btn-primary" onClick={() => window.location.href = '/budget'}>
              View Budget Dashboard
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default EnhancedBillUpload;
